import { join } from 'node:path';
import { Inject, Injectable, Logger } from '@nestjs/common';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { Pool } from 'pg';
import { PG_POOL } from './database.tokens';

/** Arbitrary constant; all API replicas take this advisory lock so only one migrates at a time. */
const MIGRATION_LOCK_ID = 727_100_001;

/** SQL migrations generated by drizzle-kit, shipped next to dist/ (package "files"). */
export const MIGRATIONS_FOLDER = join(__dirname, '..', '..', 'drizzle');

@Injectable()
export class MigrationRunner {
  private readonly logger = new Logger(MigrationRunner.name);

  constructor(@Inject(PG_POOL) private readonly pool: Pool) {}

  async run(): Promise<void> {
    const client = await this.pool.connect();
    try {
      await client.query('SELECT pg_advisory_lock($1)', [MIGRATION_LOCK_ID]);
      const started = Date.now();
      await migrate(drizzle(client), { migrationsFolder: MIGRATIONS_FOLDER });
      this.logger.log(`Database migrations up to date (${Date.now() - started} ms)`);
    } finally {
      await client.query('SELECT pg_advisory_unlock($1)', [MIGRATION_LOCK_ID]).catch(() => undefined);
      client.release();
    }
  }
}
